export const materialValues={p:1,n:3,b:3,r:5,q:9,k:0};
export function materialSummary(chess){const totals={w:0,b:0},captured={w:[],b:[]};for(const p of chess.board().flat().filter(Boolean))totals[p.color]+=materialValues[p.type];for(const m of chess.history({verbose:true}))if(m.captured)captured[m.color].push(m.captured);for(const c of ['w','b'])captured[c].sort((a,b)=>materialValues[b]-materialValues[a]);return{captured,advantage:{w:Math.max(0,totals.w-totals.b),b:Math.max(0,totals.b-totals.w)}}}
export function materialHTML(summary,color){const enemy=color==='w'?'b':'w',names={p:'pedone',n:'cavallo',b:'alfiere',r:'torre',q:'donna'};return `<span>Pezzi catturati</span>${summary.captured[color].map(p=>`<img src="pieces/${enemy}${p.toUpperCase()}.png" alt="${names[p]}">`).join('')}${summary.advantage[color]?`<strong aria-label="Vantaggio materiale ${summary.advantage[color]}">+${summary.advantage[color]}</strong>`:''}`}
